  "footer.text": { en: "Part of <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Chapter 13: Case Studies for Multiple Regression · by Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", es: "Parte de <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Capítulo 13: Estudios de caso para regresión múltiple · por Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>" },
