  "widget.cd.callout": { en: "<strong>Capital elasticity α = {alpha}</strong>, <strong>labor elasticity β = {beta}</strong>. Sum = {sum} ≈ 1. The F-test for constant returns to scale gives p = {crs_p} — we cannot reject CRS at any conventional level.", es: "<strong>Elasticidad del capital α = {alpha}</strong>, <strong>elasticidad del trabajo β = {beta}</strong>. Suma = {sum} ≈ 1. La prueba F para rendimientos constantes a escala da p = {crs_p} — no podemos rechazar RCE en ningún nivel convencional." },
  "widget.cd.chart.actual": { en: "Actual output", es: "Producción real" },
